const dag = $workflow.staticData.dagState || {};
dag.builtImages = dag.builtImages || {};
dag.builtImages[$json.body.service] = { rcTag: $json.body.rc_tag, image: $json.body.image, builtAt: new Date().toISOString() };
$workflow.staticData.dagState = dag;
return [{ json: { status: 'state-updated', service: $json.body.service, rcTag: $json.body.rc_tag, message: 'ArgoCD Image Updater handles SIT deploy automatically' } }];
